base_pip_total.formula:
profile_id = $equipment_revision.chassis_profile.base_martial_profile_id
entries = Damage_profile_entries.lookupRecords(profile_id=profile_id)
return sum(int(entry.base_pips or 0) for entry in entries)

m_c11_state.formula:
if not $equipment_revision or $hand_assignment != 'off_hand':
  return 'unaffected'
if $equipment_revision.category.category_id != 'weapon' or $equipment_revision.chassis_profile.handedness != 'one_handed':
  return 'unaffected'
entries = Damage_profile_entries.lookupRecords(profile_id=$equipment_revision.chassis_profile.base_martial_profile_id)
return 'applied' if entries else 'missing_profile'

effective_pip_total.formula:
if $m_c11_state == 'missing_profile':
  return None
return $base_pip_total - (1 if $m_c11_state == 'applied' else 0)

effective_damage_preview.formula:
profile_id = $equipment_revision.chassis_profile.base_martial_profile_id
entries = list(Damage_profile_entries.lookupRecords(profile_id=profile_id))
entries.sort(key=lambda e: (int(e.sort_order or 0), e.id))
if not entries:
  return 'MISSING PROFILE'
top = max(int(e.base_pips or 0) for e in entries)
chosen = max(i for i,e in enumerate(entries) if int(e.base_pips or 0) == top)
parts = []
for i,e in enumerate(entries):
  pips = int(e.base_pips or 0) - (1 if $m_c11_state == 'applied' and i == chosen else 0)
  if pips > 0:
    parts.append('%s %s' % (e.damage_type.damage_type_id, '+' * pips))
return ', '.join(parts)
